def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply():
        op = operators.pop()

        if op == "~":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ValueError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ValueError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            if op == "/":
                values.append(quotient)
            else:
                values.append(a - b * quotient)

    i = 0
    expect_operand = True

    try:
        while i < len(expr):
            char = expr[i]

            if char.isspace():
                i += 1
            elif "0" <= char <= "9":
                value = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    value = value * 10 + (ord(expr[i]) - ord("0"))
                    i += 1
                values.append(value)
                expect_operand = False
            elif char == "(":
                operators.append(char)
                i += 1
                expect_operand = True
            elif char == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                i += 1
                expect_operand = False
            elif char == "-" and expect_operand:
                operators.append("~")
                i += 1
            else:
                while (
                    operators
                    and operators[-1] != "("
                    and (
                        precedence[operators[-1]] > precedence[char]
                        or (
                            precedence[operators[-1]] == precedence[char]
                            and char != "^"
                        )
                    )
                ):
                    apply()
                operators.append(char)
                i += 1
                expect_operand = True

        while operators:
            apply()

        return values[0]
    except ValueError:
        return "error"
